#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MiniCut 32(V17) - Code & Preview Performance Optimise

* FIXED: Mask preview not updating when proxy is enabled. The mask shape
  cache (_mask_cache) was never cleared on project edits, so adjusting mask
  position, feather or invert had no visible effect until restart.

* FIXED: "Copy background" effect filled the spill border with transparency
  instead of a blurred copy of the clip. Now uses reflected pixels so the
  enlarged copy fills the empty area around the media correctly.

* PERFORMANCE - Code:
  - _plans() indexes active clips by track ID; cuts O(clips*tracks) to
    O(clips+tracks).
  - _snapshot_for() reuses the JSON fingerprint from the content check;
    eliminates the second full serialisation per edit.
  - RenderWorker.run() skips rendering when the same frame (version+time+
    quality) was already emitted, avoiding redundant composites on UI repaints.
  - request_render() caches display_scale() for 250 ms instead of querying
    Qt layout on every playback tick.
  - _fx_cache entry limit 8->32; mask cache limit 24->48.

* PERFORMANCE - Preview quality:
  - _adaptive_scale() uses a faster EMA when render times drop so preview
    quality recovers quickly after heavy segments.

* UI: Patches 33+ now show as 32(V1), 32(V2), ... in the Launcher.

Files changed: minicut/render/renderer.py, minicut/render/fxpack/color.py,
               minicut/render/preview.py, MiniCut_Launcher.pyw
  python Patch/apply_49_code_perf_optimize.py --check
  python Patch/apply_49_code_perf_optimize.py
  python Patch/apply_49_code_perf_optimize.py --revert
Close MiniCut before installing.
"""
import base64, datetime, hashlib, json, os, shutil, sys, zlib
PATCH_NAME = "patch49_code_perf_optimize"
REPLACE = {
  "minicut/render/renderer.py": {
    "base": "91433c6339f68722c1596955380625f061ceaa6557061a04ed222ba9be2b43d3",
    "new": "2f05edc3042ad105fb1fe7cd95526b504dcb05add751fc1c04c17e28c9a579f1"
  },
  "minicut/render/fxpack/color.py": {
    "base": "aea26de6e93050e57b4b078e8437b16b2ebd0becd87ba80f17c4cc724a418c56",
    "new": "1f4863c6b0922ac22b8f7236e43c78c921db0525010124a662166e9b63fd89f7"
  },
  "minicut/render/preview.py": {
    "base": "397d1ce0062cb057a7c04dcf1ebc409908710b1c02dd7cc07fd0e21595332467",
    "new": "1d3e876b9a6b7a32075bfeb4bdb0849c8245b6f9843ea50add2c8ba9e103eb45"
  }
}
NEW_FILES = {}
PAYLOAD = {"minicut/render/renderer.py": "", "minicut/render/fxpack/color.py": "", "minicut/render/preview.py": "", "MiniCut_Launcher.pyw": ""}

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = HERE if os.path.isfile(os.path.join(HERE, "minicut", "app.py")) else (os.path.dirname(HERE) if os.path.isfile(os.path.join(os.path.dirname(HERE), "minicut", "app.py")) else HERE)
BACKUP_ROOT = os.path.join(ROOT, "_patch_backup")


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(ROOT, *rel.split("/"))
def decode(s): return zlib.decompress(base64.b64decode(s))
def _read(rel):
    try:
        with open(path_of(rel), "rb") as f: return f.read()
    except FileNotFoundError: return None


def check_only():
    print("Checking 32(V17) / patch 49 ...")
    ok = True
    for rel, hashes in REPLACE.items():
        data = _read(rel)
        if data is None: print("  MISSING:", rel); ok = False; continue
        h = norm_hash(data)
        if h == hashes["new"]: print("  installed:", rel)
        elif h == hashes["base"]: print("  ready:", rel)
        else: print("  conflict:", rel); ok = False
    return ok


def install():
    ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = os.path.join(BACKUP_ROOT, ts)
    os.makedirs(backup, exist_ok=True)
    manifest = {"_launcher": {"label": "32(V17)", "patch": PATCH_NAME}, "files": {}}
    # Pre-check
    for rel, hashes in REPLACE.items():
        data = _read(rel)
        if data is None: print("Missing:", rel); return False
        h = norm_hash(data)
        if h == hashes["new"]: continue   # already done
        if h != hashes["base"]: print("Conflict in", rel); return False
    # Backup originals
    for rel in list(REPLACE.keys()) + ["MiniCut_Launcher.pyw"]:
        data = _read(rel)
        if data is None: continue
        bk = os.path.join(backup, *rel.replace("/", os.sep).split(os.sep))
        os.makedirs(os.path.dirname(bk), exist_ok=True)
        shutil.copy2(path_of(rel), bk)
        manifest["files"][rel] = {"orig": norm_hash(data)}
    # Write new files
    for rel, payload_b64 in PAYLOAD.items():
        new_data = decode(payload_b64)
        dest = path_of(rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as f: f.write(new_data)
        print("  installed:", rel)
    with open(os.path.join(backup, "manifest.json"), "w") as f:
        json.dump(manifest, f, indent=2)
    print("32(V17) installed. Backup:", backup)
    return True


def revert():
    if not os.path.isdir(BACKUP_ROOT): print("No backups found."); return False
    backups = sorted([d for d in os.listdir(BACKUP_ROOT) if os.path.isdir(os.path.join(BACKUP_ROOT, d))], reverse=True)
    for ts in backups:
        mf = os.path.join(BACKUP_ROOT, ts, "manifest.json")
        if not os.path.isfile(mf): continue
        with open(mf) as f: man = json.load(f)
        if man.get("_launcher", {}).get("patch") != PATCH_NAME: continue
        print("Reverting from backup", ts)
        for rel in man.get("files", {}):
            src = os.path.join(BACKUP_ROOT, ts, *rel.replace("/", os.sep).split(os.sep))
            if os.path.isfile(src): shutil.copy2(src, path_of(rel)); print("  restored:", rel)
        print("Done."); return True
    print("No backup for this patch."); return False


if __name__ == "__main__":
    if "--check" in sys.argv: sys.exit(0 if check_only() else 1)
    if "--revert" in sys.argv: sys.exit(0 if revert() else 1)
    sys.exit(0 if install() else 1)
